*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/bns_common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS10002.gfm';
scwin.pMktactCd;
scwin.pIsuCd;
scwin.pBndApplId;
scwin.pAddIsuAmt;
scwin.pBndListProcsTpCd;

	//----W-Craft WebSquare 변환 확인: fn_SetPar----//

	//----W-Craft WebSquare 변환 확인: fn_GetPar----//
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vStripAmtCfm;
scwin.arrPar = new Array();
scwin.sum_StripNsPrtBal_1;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/********************************************** 

	//----W-Craft WebSquare 변환 확인: fn_SetPar----//
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/

	//----W-Craft WebSquare 변환 확인: fn_SetPar----//
scwin.fn_SetParam = function() {

	//----W-Craft WebSquare 변환 확인: Provider----//
    var prt = frame.Provider("../");
    if (prt != undefined) {

	//----W-Craft WebSquare 변환 확인: fn_GetPar----//
        scwin.fn_GetPar = prt.scwin.fn_GetPar;

	//----W-Craft WebSquare 변환 확인: fn_SetPar----//
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }

	//----W-Craft WebSquare 변환 확인: fn_GetPar----//
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();

	//----W-Craft WebSquare 변환 확인: fn_GetPar----//
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vStripAmtCfm = scwin.arrPar[0].VIEW_YN;
        scwin.pMktactCd = scwin.arrPar[0].BND_MKTACT_TP_CD;
        scwin.pIsuCd = scwin.arrPar[0].ISU_CD;
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
        scwin.pBndListProcsTpCd = scwin.arrPar[0].BND_LIST_PROCS_TP_CD;
    }
};



/********************************************** 
 * 함수명   : fn_SearchProc
 * 설명       : 처리완료 시 조회
 ***********************************************/
scwin.fn_SearchProc = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.pBndApplId;
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.pBndListProcsTpCd;
    param += "&{P}V_ISU_CD=" + scwin.pIsuCd;
    var dsNm = 'BNS_ADD_AND_STRIP_INTEG';
    var qryId = 'lds.stf.bnschg.select.readAddAndStripInteg';
    if (scwin.vStripAmtCfm != "View") {
        qryId = 'lds.stf.bnschg.select.readStripRelInfoAddBnd';
    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_AddAndStrip, dsNm, qryId, param);
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo);
    $c.bns.BnsPanelToGroupBox(pnl_Group);
    $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
    $c.bns.BnsPanelToGroupBox(pnl_AddInfo);
    $c.bns.BnsPanelToGroupBox(pnl_StripNew);
    $c.bns.BnsPanelToGroupBox(pnl_StripAdd);
    $c.bns.BnsPanelToGroupBox(pnl_MktactAmt);
    //호출파라미터설정

	//----W-Craft WebSquare 변환 확인: fn_SetPar----//
    scwin.fn_SetParam();
    //저장버튼 숨김여부
    if (scwin.vStripAmtCfm == "View") {
        //당일 스트립 팝업 시
        $c.stf.showObj(btn_Save, false);
    } else {
        //처리완료 시
        $c.stf.showObj(btn_Save, true);
    }
    scwin.fn_SearchProc();
};
scwin.dts_AddAndStrip_OnLoadCompleted = function(rowcount) {
    edt_IsuAmt.RightMargin = 5;
    edt_ListAmt.RightMargin = 5;
    edt_BfchgStripNsprtBal.RightMargin = 5;
    edt_AddIsuAmt.RightMargin = 5;
    edt_StripApplAmt.RightMargin = 5;
    edt_StripParTotAmt.RightMargin = 5;
    edt_UnParTotAmt.RightMargin = 5;
    edt_AfchgIsuAmt.RightMargin = 5;
    edt_AfchgListAmt.RightMargin = 5;
    edt_AfchgStripNsprtBal.RightMargin = 5;
};
scwin.btn_Save_onclick = function(e) {
    if (scwin.pMktactCd != '305') {
        scwin.arrPar[0] = {
            REG_YN: 'Y',

	//----W-Craft WebSquare 변환 확인: NameValue----//
            ADD_LIST_APPL_ID: dts_AddAndStrip.NameValue(1, 'ADD_LIST_APPL_ID'),

	//----W-Craft WebSquare 변환 확인: NameValue----//
            STRIP_APPL_ID: dts_AddAndStrip.NameValue(1, 'STRIP_APPL_ID'),

	//----W-Craft WebSquare 변환 확인: NameValue----//
            ADD_STRIP_APPL_ID: dts_AddAndStrip.NameValue(1, 'ADD_STRIP_APPL_ID'),

	//----W-Craft WebSquare 변환 확인: NameValue----//
            AFCHG_ISU_AMT: dts_AddAndStrip.NameValue(1, 'AFCHG_ISU_AMT'),

	//----W-Craft WebSquare 변환 확인: NameValue----//
            AFCHG_LIST_AMT: dts_AddAndStrip.NameValue(1, 'AFCHG_LIST_AMT'),

	//----W-Craft WebSquare 변환 확인: NameValue----//
            AFCHG_STRIP_NSPRT_BAL: dts_AddAndStrip.NameValue(1, 'AFCHG_STRIP_NSPRT_BAL')
        };
    } else {

	//----W-Craft WebSquare 변환 확인: Provider----//
        var prt = frame.Provider("../");

	//----W-Craft WebSquare 변환 확인: ImportData----//

	//----W-Craft WebSquare 변환 확인: ExportData----//
        prt.dts_AddAndStrip.ImportData(dts_AddAndStrip.ExportData(1, dts_AddAndStrip.CountRow, false));
        scwin.arrPar[0] = {
            REG_YN: "Y"
        };
    }

	//----W-Craft WebSquare 변환 확인: fn_SetPar----//
    scwin.fn_SetPar(scwin.arrPar);

	//----W-Craft WebSquare 변환 확인: CloseFrame----//
    frame.CloseFrame();
};
scwin.btn_Close_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: CloseFrame----//
    frame.CloseFrame();
};
scwin.edt_IsuAmt_OnKillFocus = function() {
    edt_IsuAmt.RightMargin = 5;
